"use client";

import * as React from "react";
import { ArrowDownRight, ArrowUpRight, Minus } from "lucide-react";
import { cn } from "@/lib/utils";

type Props = {
  value: number;
  percent?: number;
  currency?: string;
  /**
   * `xs` is a dense variant that drops the vertical padding — for tight
   * surfaces like the dashboard marquee where a full badge would blow out the
   * row height. Replaces the previous `!py-0` utility override.
   */
  size?: "xs" | "sm" | "md";
  className?: string;
  showSign?: boolean;
};

export function PnLBadge({
  value,
  percent,
  currency = "$",
  size = "md",
  className,
  showSign = true,
}: Props) {
  const variant: "bull" | "bear" | "neutral" =
    Math.abs(value) < 1e-6 ? "neutral" : value > 0 ? "bull" : "bear";

  const sign = value > 0 ? "+" : value < 0 ? "" : "";
  const dollar = `${sign}${currency}${Math.abs(value).toFixed(2)}`;
  // A divide-by-zero upstream yields Infinity/NaN, which `toFixed` renders as
  // a literal "Infinity%" or "NaN%". Showing no percentage is more honest than
  // showing a fabricated one.
  const pct =
    percent === undefined || !Number.isFinite(percent)
      ? null
      : `${percent > 0 ? "+" : ""}${percent.toFixed(2)}%`;

  const Icon = variant === "bull" ? ArrowUpRight : variant === "bear" ? ArrowDownRight : Minus;

  const base = "inline-flex items-center gap-1 rounded-md font-medium tabular-nums";
  const sizing =
    size === "xs"
      ? "text-xs px-1.5 py-0"
      : size === "sm"
        ? "text-xs px-1.5 py-0.5"
        : "text-sm px-2 py-1";
  const palette =
    variant === "bull"
      ? "bg-[var(--color-bull-soft)] text-[var(--color-bull-fg)]"
      : variant === "bear"
        ? "bg-[var(--color-bear-soft)] text-[var(--color-bear-fg)]"
        : "bg-muted text-muted-foreground";

  return (
    <span className={cn(base, sizing, palette, className)}>
      <Icon className="size-3" aria-hidden="true" />
      {showSign && <span>{dollar}</span>}
      {pct !== null && <span className="opacity-75">{pct}</span>}
    </span>
  );
}
